/**
 * Keeps a horizontal product-carousel gesture from activating the product
 * link that sits underneath the pointer when the gesture ends.
 *
 * The carousel itself remains native: this listener never prevents pointer
 * movement, so the browser still decides between horizontal carousel scroll
 * and vertical page scroll. It only cancels the follow-up click after a
 * clearly moved gesture, and only inside the homepage carousel.
 */
(() => {
  const gestureStates = new WeakMap();
  const moveThreshold = 8;
  const interactiveSelector = 'button, input, label, select, textarea, [role="button"], [data-no-carousel-gesture]';

  const getCarousel = (target) => {
    if (!(target instanceof Element)) return null;
    return target.closest('[data-brunito-home-product-carousel]');
  };

  document.addEventListener(
    'pointerdown',
    (event) => {
      if (!event.isPrimary) return;

      const carousel = getCarousel(event.target);
      if (!carousel || event.target.closest(interactiveSelector)) return;

      gestureStates.set(carousel, {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        moved: false,
        horizontal: false,
      });
    },
    true
  );

  document.addEventListener(
    'pointermove',
    (event) => {
      if (!event.isPrimary) return;

      const carousel = getCarousel(event.target);
      const state = carousel && gestureStates.get(carousel);
      if (!state || state.pointerId !== event.pointerId || state.moved) return;

      const deltaX = event.clientX - state.startX;
      const deltaY = event.clientY - state.startY;
      const distance = Math.hypot(deltaX, deltaY);

      if (distance < moveThreshold) return;
      state.moved = true;
      state.horizontal = Math.abs(deltaX) > Math.abs(deltaY);
    },
    true
  );

  document.addEventListener(
    'pointerup',
    (event) => {
      if (!event.isPrimary) return;

      const carousel = getCarousel(event.target);
      const state = carousel && gestureStates.get(carousel);
      if (!state || state.pointerId !== event.pointerId) return;

      if (state.moved) {
        state.suppressClick = true;
        window.setTimeout(() => {
          if (gestureStates.get(carousel) === state) gestureStates.delete(carousel);
        }, 500);
      } else {
        gestureStates.delete(carousel);
      }
    },
    true
  );

  document.addEventListener(
    'pointercancel',
    (event) => {
      if (!event.isPrimary) return;
      const carousel = getCarousel(event.target);
      const state = carousel && gestureStates.get(carousel);
      if (state?.pointerId === event.pointerId) gestureStates.delete(carousel);
    },
    true
  );

  document.addEventListener(
    'click',
    (event) => {
      const carousel = getCarousel(event.target);
      const state = carousel && gestureStates.get(carousel);
      if (!state?.suppressClick) return;

      event.preventDefault();
      event.stopImmediatePropagation();
      gestureStates.delete(carousel);
    },
    true
  );
})();
